// Domain objects stored in the library database.
namespace LibraryService.Models;

/// <summary>
/// One favorite: a snapshot of a game, saved for one anonymous browser.
/// The snapshot (name, cover, rating, date) is copied from catalog-service
/// at the moment of saving, so the favorites list can be shown without
/// calling the catalog again.
/// </summary>
public class FavoriteGame
{
    /// <summary>Random ID generated by the browser; identifies whose favorite this is.</summary>
    public Guid ClientId { get; set; }

    /// <summary>RAWG's ID of the game (same ID catalog-service uses).</summary>
    public int GameId { get; set; }

    /// <summary>Title of the game at the time it was saved.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Cover image URL, or null if the game has none.</summary>
    public string? CoverUrl { get; set; }

    /// <summary>Average user rating at the time it was saved.</summary>
    public double Rating { get; set; }

    /// <summary>Release date, or null if unknown.</summary>
    public DateOnly? ReleaseDate { get; set; }

    /// <summary>When the user added the game (UTC); used to sort the list.</summary>
    public DateTime AddedAtUtc { get; set; }
}
